long distance() {
    digitalWrite(9, LOW);
    delayMicroseconds(2);
    digitalWrite(9, HIGH);
    delayMicroseconds(10);
    digitalWrite(9, LOW);
    long t = pulseIn(10, HIGH);
    return t / 58;
}

void setup() {
    Serial.begin(9600);
    pinMode(9, OUTPUT);
    pinMode(10, INPUT);
}

void loop() {
    Serial.println(distance());
    delay(200);
}
